+  rangeTo,
+  onChange,
+  referenceSurah,
+  referenceAyah,
+  referencePage,
+  portalContainer,
+}: {
+  chapters: SurahResult[];
+  rangeTo: RangePoint | null;
+  onChange: (rangeTo: RangePoint) => void;
+  referenceSurah: number;
+  referenceAyah: number;
+  referencePage: number;
+  portalContainer: HTMLElement | null;
