+          <Input
+            type="number"
+            inputMode="numeric"
+            min={ayahFloor}
+            max={ayahCeil}
+            value={ayahInput}
+            className="w-20 shrink-0"
+            onChange={(e) => setAyahInput(e.target.value)}
+            onBlur={commitAyah}
+            onKeyDown={(e) => {
+              if (e.key === "Enter") e.currentTarget.blur();
+            }}
+          />
+        </div>
+      )}
+    </div>
+  );
+};
